    def test_quantifier_scope_ambiguity_accepts_universal_existential_mix(self) -> None:
        subject_universal = run_pipeline("every boy loves a girl", require_coq=True)
        self.assertTrue(subject_universal["ok"])
        self.assertEqual(subject_universal["kind"], "quantifier_scope_ambiguity")
        self.assertEqual(subject_universal["ast"]["quantifier"], "mixed")
        self.assertEqual(
            subject_universal["ast"]["quantifiers"],
            {"subject": "every", "object": "a"},
        )
        self.assertEqual(
            [reading["name"] for reading in subject_universal["semantic_readings"]],
            ["every_boy_wide_scope", "a_girl_wide_scope"],
        )
        self.assertEqual(
            subject_universal["semantic_readings"][0]["dependent_type_translation"],
            (
                "forall x_boy : Entity. boy(x_boy) -> exists x_girl : Entity. "
                "girl(x_girl) and love(x_boy, x_girl)"
            ),
        )
        self.assertEqual(
            subject_universal["semantic_readings"][1]["dependent_type_translation"],
            (
                "exists x_girl : Entity. girl(x_girl) and "
                "(forall x_boy : Entity. boy(x_boy) -> love(x_boy, x_girl))"
            ),
        )
        self.assertIn(
            "Definition every_boy_wide_scope : Prop := "
            "forall x_boy : Entity, boy x_boy -> exists x_girl : Entity",
            subject_universal["coq_code"],
        )
        self.assertIn(
            "Definition a_girl_wide_scope : Prop := "
            "exists x_girl : Entity, girl x_girl /\\ "
            "(forall x_boy : Entity, boy x_boy -> love x_boy x_girl).",
            subject_universal["coq_code"],
        )
        self.assertIn("Parameter boy : Entity -> Prop.", subject_universal["coq_code"])
        self.assertIn("Parameter girl : Entity -> Prop.", subject_universal["coq_code"])
        self.assertNotIn("Parameter every : Entity.", subject_universal["coq_code"])
        self.assertNotIn("Parameter a : Entity.", subject_universal["coq_code"])
        self.assertEqual(
            [binder["quantifier"] for binder in subject_universal["ast"]["readings"][0]["scope_order"]],
            ["every", "a"],
        )
        self.assertEqual(subject_universal["coq_check"]["status"], "passed")

        object_universal = run_pipeline("a boy loves every girl", require_coq=True)
        self.assertTrue(object_universal["ok"])
        self.assertEqual(object_universal["kind"], "quantifier_scope_ambiguity")
        self.assertEqual(
            [reading["name"] for reading in object_universal["semantic_readings"]],
            ["a_boy_wide_scope", "every_girl_wide_scope"],
        )
        self.assertEqual(
            object_universal["semantic_readings"][0]["dependent_type_translation"],
            (
                "exists x_boy : Entity. boy(x_boy) and "
                "(forall x_girl : Entity. girl(x_girl) -> love(x_boy, x_girl))"
            ),
        )
        self.assertEqual(
            object_universal["semantic_readings"][1]["dependent_type_translation"],
            (
                "forall x_girl : Entity. girl(x_girl) -> exists x_boy : Entity. "
                "boy(x_boy) and love(x_boy, x_girl)"
            ),
        )
        self.assertEqual(object_universal["coq_check"]["status"], "passed")

        modified = run_pipeline(
            "In the bathroom every boy loved a girl yesterday",
            require_coq=True,
        )
        self.assertTrue(modified["ok"])
        self.assertEqual(modified["kind"], "quantifier_scope_ambiguity")
        self.assertEqual(modified["ast"]["modifiers"][0]["name"], "in_bathroom")
        self.assertEqual(
            modified["ast"]["readings"][0]["time_modifiers"],
            [{"operator": "at", "argument": "yesterday"}],
        )
        self.assertIn(
            "at_T(yesterday, forall x_boy : Entity. boy(x_boy) -> "
            "exists x_girl : Entity. girl(x_girl) and "
            "love(1)(in(bathroom), x_boy, x_girl))",
            modified["semantic_readings"][0]["dependent_type_translation"],
        )
        self.assertIn(
            "Parameter love : forall n : nat, ModifierSeq n -> Entity -> Entity -> PropT.",
            modified["coq_code"],
        )
        self.assertEqual(modified["coq_check"]["status"], "passed")

    def test_quantifier_scope_ambiguity_accepts_negative_existential_mix(self) -> None:
        subject_negative = run_pipeline("no boy loves a girl", require_coq=True)
        self.assertTrue(subject_negative["ok"])
        self.assertEqual(subject_negative["kind"], "quantifier_scope_ambiguity")
        self.assertEqual(subject_negative["ast"]["quantifier"], "mixed_negative")
        self.assertEqual(
            subject_negative["ast"]["quantifiers"],
            {"subject": "no", "object": "a"},
        )
        self.assertEqual(
            [reading["name"] for reading in subject_negative["semantic_readings"]],
            ["no_boy_wide_scope", "a_girl_wide_scope"],
        )
        self.assertEqual(
            subject_negative["semantic_readings"][0]["dependent_type_translation"],
            (
                "forall x_boy : Entity. boy(x_boy) -> not "
                "(exists x_girl : Entity. girl(x_girl) and love(x_boy, x_girl))"
            ),
        )
        self.assertEqual(
            subject_negative["semantic_readings"][1]["dependent_type_translation"],
            (
                "exists x_girl : Entity. girl(x_girl) and "
                "(forall x_boy : Entity. boy(x_boy) -> not (love(x_boy, x_girl)))"
            ),
        )
        self.assertIn(
            "Definition no_boy_wide_scope : Prop := "
            "forall x_boy : Entity, boy x_boy -> "
            "~ (exists x_girl : Entity, girl x_girl /\\ love x_boy x_girl).",
            subject_negative["coq_code"],
        )
        self.assertIn(
            "Definition a_girl_wide_scope : Prop := "
            "exists x_girl : Entity, girl x_girl /\\ "
            "(forall x_boy : Entity, boy x_boy -> ~ (love x_boy x_girl)).",
            subject_negative["coq_code"],
        )
        self.assertNotIn("Parameter no : Entity.", subject_negative["coq_code"])
        self.assertNotIn("Parameter a : Entity.", subject_negative["coq_code"])
        self.assertEqual(
            [binder["quantifier"] for binder in subject_negative["ast"]["readings"][0]["scope_order"]],
            ["no", "a"],
        )
        self.assertEqual(subject_negative["coq_check"]["status"], "passed")

        object_negative = run_pipeline("a boy loves no girl", require_coq=True)
        self.assertTrue(object_negative["ok"])
        self.assertEqual(object_negative["kind"], "quantifier_scope_ambiguity")
        self.assertEqual(
            [reading["name"] for reading in object_negative["semantic_readings"]],
            ["a_boy_wide_scope", "no_girl_wide_scope"],
        )
        self.assertEqual(
            object_negative["semantic_readings"][0]["dependent_type_translation"],
            (
                "exists x_boy : Entity. boy(x_boy) and "
                "(forall x_girl : Entity. girl(x_girl) -> not (love(x_boy, x_girl)))"
            ),
        )
        self.assertEqual(
            object_negative["semantic_readings"][1]["dependent_type_translation"],
            (
                "forall x_girl : Entity. girl(x_girl) -> not "
                "(exists x_boy : Entity. boy(x_boy) and love(x_boy, x_girl))"
            ),
        )
        self.assertEqual(object_negative["coq_check"]["status"], "passed")

        modified = run_pipeline(
            "In the bathroom no boy loved a girl yesterday",
            require_coq=True,
        )
        self.assertTrue(modified["ok"])
        self.assertEqual(modified["kind"], "quantifier_scope_ambiguity")
        self.assertEqual(modified["ast"]["modifiers"][0]["name"], "in_bathroom")
        self.assertEqual(
            modified["ast"]["readings"][0]["time_modifiers"],
            [{"operator": "at", "argument": "yesterday"}],
        )
        self.assertIn(
            "at_T(yesterday, forall x_boy : Entity. boy(x_boy) -> not "
            "(exists x_girl : Entity. girl(x_girl) and "
            "love(1)(in(bathroom), x_boy, x_girl)))",
            modified["semantic_readings"][0]["dependent_type_translation"],
        )
        self.assertNotIn("in_bathroom_no", modified["dependent_type_translation"])
        self.assertEqual(modified["coq_check"]["status"], "passed")

    def test_quantifier_scope_ambiguity_preserves_time_modifiers(self) -> None:
        trailing = run_pipeline("some boy loves some girl yesterday", require_coq=True)
        self.assertTrue(trailing["ok"])
        self.assertEqual(trailing["kind"], "quantifier_scope_ambiguity")
        self.assertEqual(
            trailing["ast"]["readings"][0]["time_modifiers"],
            [{"operator": "at", "argument": "yesterday"}],
        )
        self.assertEqual(
            trailing["event_semantics"]["time_modifiers"],
            [{"operator": "at", "argument": "yesterday"}],
        )
        self.assertEqual(
            trailing["semantic_readings"][0]["dependent_type_translation"],
            (
                "at_T(yesterday, exists x_boy : Entity. boy(x_boy) and "
                "exists x_girl : Entity. girl(x_girl) and love(x_boy, x_girl))"
            ),
        )
        self.assertEqual(
            trailing["semantic_readings"][1]["dependent_type_translation"],
            (
                "at_T(yesterday, exists x_girl : Entity. girl(x_girl) and "
                "exists x_boy : Entity. boy(x_boy) and love(x_boy, x_girl))"
            ),
        )
        self.assertIn("Parameter yesterday : Entity.", trailing["coq_code"])
        self.assertIn("Parameter at_T : Entity -> Prop -> Prop.", trailing["coq_code"])
        self.assertIn(
            "at_T yesterday (exists x_boy : Entity, boy x_boy",
            trailing["coq_code"],
        )
        self.assertNotIn("Parameter some_boy : Entity.", trailing["coq_code"])
        self.assertNotIn("Parameter some_girl : Entity.", trailing["coq_code"])
        self.assertNotIn("Parameter Event : Type.", trailing["coq_code"])
        self.assertEqual(trailing["semantic_readings_check"]["ok"], True)
        self.assertEqual(trailing["coq_check"]["status"], "passed")

        fronted = run_pipeline("yesterday some boy loves some girl", require_coq=True)
        self.assertTrue(fronted["ok"])
        self.assertEqual(fronted["kind"], "quantifier_scope_ambiguity")
        self.assertEqual(
            fronted["semantic_readings"][0]["dependent_type_translation"],
            trailing["semantic_readings"][0]["dependent_type_translation"],
        )
        self.assertEqual(fronted["coq_check"]["status"], "passed")

        interval = run_pipeline("some boy loves some girl in the morning", require_coq=True)
        self.assertTrue(interval["ok"])
        self.assertEqual(interval["kind"], "quantifier_scope_ambiguity")
        self.assertEqual(
            interval["ast"]["readings"][0]["time_modifiers"],
            [{"operator": "during", "argument": "morning"}],
        )
        self.assertIn(
            "during_T(morning, exists x_boy : Entity.",
            interval["semantic_readings"][0]["dependent_type_translation"],
        )
        self.assertIn("Parameter during_T : Entity -> Prop -> Prop.", interval["coq_code"])
        self.assertEqual(interval["coq_check"]["status"], "passed")

    def test_quantifier_scope_ambiguity_preserves_adv_modifiers(self) -> None:
        location = run_pipeline("some boy loved some girl in the bathroom", require_coq=True)
        self.assertTrue(location["ok"])
        self.assertEqual(location["kind"], "quantifier_scope_ambiguity")
        self.assertEqual(
            location["ast"]["modifiers"],
            [
                {
                    "expression": "in(bathroom)",
                    "name": "in_bathroom",
                    "type": "Adv",
                    "semantic_role": "Location",
                    "surface_lexicon": {
                        "surface_modifier": "in(bathroom)",
                        "normalized_modifier": "in_bathroom",
                        "type": "Adv",
                        "semantic_role": "Location",
                        "source": "translator/surface_lexicon.py",
                    },
                }
            ],
        )
        self.assertEqual(location["ast"]["readings"][0]["modifiers"], location["ast"]["modifiers"])
        self.assertEqual(
            [variant["kind"] for variant in location["ast"]["attachment_variants"]],
            ["clause_adv", "object_np_restrictor"],
        )
        self.assertEqual(
            [reading["name"] for reading in location["semantic_readings"]],
            [
                "some_boy_wide_scope_clause_adv",
                "some_girl_wide_scope_clause_adv",
                "some_boy_wide_scope_object_np_restrictor",
                "some_girl_wide_scope_object_np_restrictor",
            ],
        )
        self.assertEqual(
            location["ast"]["readings"][0]["relation"]["predicate_type"],
            "forall n : nat, ModifierSeq n -> Entity -> Entity -> PropT",
        )
        self.assertEqual(
            location["semantic_readings"][0]["dependent_type_translation"],
            (
                "exists x_boy : Entity. boy(x_boy) and exists x_girl : Entity. "
                "girl(x_girl) and love(1)(in(bathroom), x_boy, x_girl)"
            ),
        )
        self.assertEqual(
            location["semantic_readings"][1]["dependent_type_translation"],
            (
                "exists x_girl : Entity. girl(x_girl) and exists x_boy : Entity. "
                "boy(x_boy) and love(1)(in(bathroom), x_boy, x_girl)"
            ),
        )
        self.assertEqual(
            location["semantic_readings"][2]["dependent_type_translation"],
            (
                "exists x_boy : Entity. boy(x_boy) and exists x_girl : Entity. "
                "(girl(x_girl) and in_bathroom_np(x_girl)) and "
                "love(0)(x_boy, x_girl)"
            ),
        )
        self.assertEqual(
            location["semantic_readings"][0]["attachment_summary"]["typed_modifiers"],
            [
                {
                    "site": "clause",
                    "name": "in_bathroom",
                    "type": "Adv",
                    "expression": "in(bathroom)",
                    "semantic_role": "Location",
                }
            ],
        )
        self.assertIn(
            "clause: in_bathroom : Adv",
            location["semantic_readings"][0]["reading_explanation"],
        )
        self.assertIn(
            "modify predicates, not Entity constants",
            location["semantic_readings"][0]["reading_explanation"],
        )
        self.assertEqual(
            location["semantic_readings"][2]["attachment_summary"]["typed_np_restrictors"],
            [
                {
                    "site": "object_np",
                    "predicate": "in_bathroom_np",
                    "predicate_type": "Entity -> Prop",
                    "expression": "in(bathroom)",
                    "semantic_role": "Location",
                }
            ],
        )
        self.assertIn(
            "object_np: in_bathroom_np : Entity -> Prop",
            location["semantic_readings"][2]["reading_explanation"],
        )
        self.assertIn(
            "constrain entity binders, not predicate-level Adv slots",
            location["semantic_readings"][2]["reading_explanation"],
        )
        self.assertEqual(
            location["semantic_readings"][3]["dependent_type_translation"],
            (
                "exists x_girl : Entity. (girl(x_girl) and in_bathroom_np(x_girl)) "
                "and exists x_boy : Entity. boy(x_boy) and love(0)(x_boy, x_girl)"
            ),
        )
        self.assertIn("Definition Adv : Type := (Entity -> PropT) -> Entity -> PropT.", location["coq_code"])
        self.assertIn("Parameter in_bathroom : Adv.", location["coq_code"])
        self.assertIn("Parameter in_bathroom_np : Entity -> Prop.", location["coq_code"])
        self.assertIn(
            "Parameter love : forall n : nat, ModifierSeq n -> Entity -> Entity -> PropT.",
            location["coq_code"],
        )
        self.assertIn(
            "love 1 (mods_cons 0 in_bathroom mods_nil) x_boy x_girl",
            location["coq_code"],
        )
        self.assertIn(
            "love 0 mods_nil x_boy x_girl",
            location["coq_code"],
        )
        self.assertNotIn("Parameter some_boy : Entity.", location["coq_code"])
        self.assertNotIn("Parameter some_girl : Entity.", location["coq_code"])
        self.assertNotIn("Parameter Event : Type.", location["coq_code"])
        self.assertTrue(location["semantic_readings_check"]["ok"])
        self.assertEqual(location["coq_check"]["status"], "passed")

