    def test_quantifier_scope_rejects_bad_np_restrictor(self) -> None:
        result = run_pipeline("some young boy loves some happy girl", require_coq=False)
        readings = result["ast"]["readings"]
        readings[0]["scope_order"][0]["restrictors"][0]["predicate_type"] = "Entity"
        type_check = check_quantifier_scope_readings(readings)
        self.assertFalse(type_check["ok"])
        self.assertIn(
            "readings[0].scope_order[0].restrictors[0] "
            "must have predicate type Entity -> Prop, Entity -> Entity -> Prop, "
            "or a ModifierSeq-indexed restrictor type",
            type_check["errors"],
        )

        readings[0]["scope_order"][0]["restrictors"] = [
            {"predicate": "young", "predicate_type": "Entity -> Prop"}
        ]
        type_check = check_quantifier_scope_readings(readings)
        self.assertFalse(type_check["ok"])
        self.assertIn(
            "readings[0].scope_order[0].restrictors must include the head predicate",
            type_check["errors"],
        )

        pp_result = run_pipeline("some boy in the park loves some happy girl", require_coq=False)
        pp_readings = pp_result["ast"]["readings"]
        pp_readings[0]["scope_order"][0]["restrictors"][1]["predicate_type"] = "Adv"
        type_check = check_quantifier_scope_readings(pp_readings)
        self.assertFalse(type_check["ok"])
        self.assertIn(
            "readings[0].scope_order[0].restrictors[1] "
            "must have predicate type Entity -> Prop, Entity -> Entity -> Prop, "
            "or a ModifierSeq-indexed restrictor type",
            type_check["errors"],
        )

        relative_result = run_pipeline(
            "some boy who saw Mary loved a girl",
            require_coq=False,
        )
        relative_readings = relative_result["ast"]["readings"]
        del relative_readings[0]["scope_order"][0]["restrictors"][1]["object"]
        type_check = check_quantifier_scope_readings(relative_readings)
        self.assertFalse(type_check["ok"])
        self.assertIn(
            "readings[0].scope_order[0].restrictors[1].object must be an object",
            type_check["errors"],
        )

        relative_np_result = run_pipeline(
            "some boy who saw a girl loved a cat",
            require_coq=False,
        )
        relative_np_readings = relative_np_result["ast"]["readings"]
        relative_np_readings[0]["scope_order"][0]["restrictors"][1][
            "object_np"
        ]["variable"] = ""
        type_check = check_quantifier_scope_readings(relative_np_readings)
        self.assertFalse(type_check["ok"])
        self.assertIn(
            "readings[0].scope_order[0].restrictors[1].object_np.variable "
            "must be non-empty",
            type_check["errors"],
        )

        relative_np_result = run_pipeline(
            "some boy who saw a girl loved a cat",
            require_coq=False,
        )
        relative_np_readings = relative_np_result["ast"]["readings"]
        relative_np_readings[0]["scope_order"][0]["restrictors"][1][
            "object_np"
        ]["restrictors"][0]["predicate_type"] = "Entity"
        type_check = check_quantifier_scope_readings(relative_np_readings)
        self.assertFalse(type_check["ok"])
        self.assertIn(
            "readings[0].scope_order[0].restrictors[1].object_np."
            "restrictors[0].predicate_type must be Entity -> Prop",
            type_check["errors"],
        )

        relative_np_result = run_pipeline(
            "some boy who saw a girl loved a cat",
            require_coq=False,
        )
        relative_np_readings = relative_np_result["ast"]["readings"]
        relative_np_readings[0]["scope_order"][0]["restrictors"][1]["object"] = {
            "name": "mary",
            "surface": "mary",
            "type": "Entity",
        }
        type_check = check_quantifier_scope_readings(relative_np_readings)
        self.assertFalse(type_check["ok"])
        self.assertIn(
            "readings[0].scope_order[0].restrictors[1] "
            "cannot contain both object and object_np",
            type_check["errors"],
        )

        relative_np_pp_result = run_pipeline(
            "some boy who saw a girl in the park loved a cat",
            require_coq=False,
        )
        relative_np_pp_readings = relative_np_pp_result["ast"]["readings"]
        relative_np_pp_readings[0]["scope_order"][0]["restrictors"][1][
            "object_np"
        ]["restrictors"][1]["predicate_type"] = "Adv"
        type_check = check_quantifier_scope_readings(relative_np_pp_readings)
        self.assertFalse(type_check["ok"])
        self.assertIn(
            "readings[0].scope_order[0].restrictors[1].object_np."
            "restrictors[1].predicate_type must be Entity -> Prop",
            type_check["errors"],
        )

        timed_relative_result = run_pipeline(
            "some boy who saw Mary yesterday loved a girl",
            require_coq=False,
        )
        timed_relative_readings = timed_relative_result["ast"]["readings"]
        timed_relative_readings[0]["scope_order"][0]["restrictors"][1][
            "time_modifiers"
        ][0]["operator"] = "inside"
        type_check = check_quantifier_scope_readings(timed_relative_readings)
        self.assertFalse(type_check["ok"])
        self.assertIn(
            "readings[0].scope_order[0].restrictors[1] "
            "time_modifiers[0].operator must be at or during",
            type_check["errors"],
        )

        adv_relative_result = run_pipeline(
            "some boy who quickly saw Mary loved a girl",
            require_coq=False,
        )
        adv_relative_readings = adv_relative_result["ast"]["readings"]
        adv_relative_readings[0]["scope_order"][0]["restrictors"][1][
            "modifiers"
        ][0]["type"] = "Entity"
        type_check = check_quantifier_scope_readings(adv_relative_readings)
        self.assertFalse(type_check["ok"])
        self.assertIn(
            "readings[0].scope_order[0].restrictors[1] modifiers[0] must have type Adv",
            type_check["errors"],
        )

        adv_relative_readings = adv_relative_result["ast"]["readings"]
        adv_relative_readings[0]["scope_order"][0]["restrictors"][1][
            "predicate_type"
        ] = "Entity -> Entity -> Prop"
        type_check = check_quantifier_scope_readings(adv_relative_readings)
        self.assertFalse(type_check["ok"])
        self.assertIn(
            "readings[0].scope_order[0].restrictors[1] "
            "must use a ModifierSeq-indexed predicate type when modifiers are present",
            type_check["errors"],
        )

