    def test_ordinary_failure_action_export_surface_covers_failure_matrix(self) -> None:
        cases = [
            ("ordinary input failure", "  ", "input", "edit_input", False, "unverified_failure", "none", None),
            ("ordinary parsing failure", "John", "parsing", "revise_sentence", False, "unverified_failure", "none", None),
            (
                "ordinary unsupported-fragment failure",
                "if John left, Mary cried because Sue left",
                "parsing",
                "revise_sentence",
                False,
                "rejected_unsupported_fragment",
                "none",
                None,
            ),
            (
                "ordinary type-check failure",
                "the plant killed",
                "type_check",
                "inspect_ast",
                True,
                "registered_construction",
                "construction_rule",
                "lexical_state_change",
            ),
        ]
        for (
            label,
            sentence,
            stage,
            action_kind,
            can_auto_run,
            scope_kind,
            certification_level,
            scope_rule,
        ) in cases:
            with self.subTest(label=label):
                result = analyze_sentence(sentence, require_coq=True)
                page = render_page(sentence, result=result, require_coq=True)
                action_bundle, status = analyze_action_export_bundle(sentence, True, 0)
                self.assertEqual(status, HTTPStatus.OK)
                self.assertEqual(result["diagnostics"]["failure_stage"], stage)
                self.assertEqual(result["verification_scope"]["kind"], scope_kind)
                self.assertEqual(
                    result["verification_scope"]["certification_level"],
                    certification_level,
                )
                self.assertEqual(result["verification_scope"]["rule_id"], scope_rule)
                self.assertEqual(action_bundle["failure_stage"], stage)
                self.assertEqual(action_bundle["action"]["kind"], action_kind)
                self.assertEqual(action_bundle["repair_plan"]["can_auto_run"], can_auto_run)

                normalized_sentence = validate_ordinary_analyze_action_export_surface(
                    label,
                    sentence,
                    True,
                    0,
                    result,
                    page,
                    action_bundle,
                    expected_failure_stage=stage,
                    expected_action_kind=action_kind,
                    expected_can_auto_run=can_auto_run,
                    expected_verification_scope_kind=scope_kind,
                    expected_certification_level=certification_level,
                    expected_verification_scope_rule=scope_rule,
                )
                self.assertEqual(normalized_sentence, result["input_sentence"])

                if can_auto_run:
                    continue
                rejection, rejection_status = analyze_action_inspection_run_bundle(
                    sentence,
                    True,
                    0,
                )
                self.assertEqual(rejection_status, HTTPStatus.BAD_REQUEST)
                validate_analyze_action_inspection_run_rejection(
                    label,
                    normalized_sentence,
                    0,
                    result,
                    rejection,
                )

    def test_analyze_action_run_api_and_page_link_ordinary_failure(self) -> None:
        sentence = "the plant killed"
        expected_path = analyze_action_run_api_path(sentence, True, 0)
        self.assertEqual(
            expected_path,
            "/api/analyze-action-run?sentence=the+plant+killed&index=0&require_coq=1",
        )
        expected_action_path = analyze_action_api_path(sentence, True, 0)
        expected_action_payload, expected_action_status = analyze_action_export_bundle(
            sentence,
            True,
            0,
        )
        self.assertEqual(expected_action_status, HTTPStatus.OK)
        expected_action_preview = html.escape(compact_json(expected_action_payload))
        page = render_page(sentence, require_coq=True)
        self.assertIn('class="next-step-action-link"', page)
        self.assertIn('href="/api/analyze-action?sentence=the+plant+killed', page)
        self.assertIn(
            'download="analyze_recovery_action__the-plant-killed__0.json"',
            page,
        )
        self.assertIn('class="next-step-action-json"', page)
        self.assertIn(
            'data-action-json-schema="diagnostic_recovery_action.v1"',
            page,
        )
        self.assertIn("<summary>Action JSON</summary>", page)
        self.assertIn(expected_action_preview, page)
        self.assertIn('class="next-step-action-run-link"', page)
        self.assertIn('href="/api/analyze-action-run?sentence=the+plant+killed', page)
        self.assertIn("require_coq=1", page)
        self.assertIn(
            'download="analyze_inspection_run__the-plant-killed__0.json"',
            page,
        )
        self.assertIn('data-inspection-json-schema="diagnostic_inspection_run.v1"', page)
        self.assertIn("&quot;source&quot;: &quot;analyze&quot;", page)
        self.assertIn("&quot;action_kind&quot;: &quot;inspect_ast&quot;", page)

        empty_page = render_page("  ", require_coq=True)
        self.assertIn('data-action-kind="edit_input"', empty_page)
        self.assertIn('href="/api/analyze-action?sentence=', empty_page)
        self.assertIn('download="analyze_recovery_action__empty-input__0.json"', empty_page)
        self.assertIn('class="next-step-action-json"', empty_page)
        self.assertIn("&quot;action_kind&quot;: &quot;edit_input&quot;", empty_page)
        self.assertNotIn("/api/analyze-action-run?sentence=", empty_page)

        with pipeline_server() as (base_url, opener):
            with opener.open(f"{base_url}{expected_action_path}", timeout=5) as response:
                action_payload = json.loads(response.read().decode("utf-8"))
            with opener.open(
                f"{base_url}{expected_action_path}&download=1",
                timeout=5,
            ) as response:
                action_download_payload = json.loads(response.read().decode("utf-8"))
                action_disposition = response.headers.get("Content-Disposition")
            with opener.open(f"{base_url}{expected_path}", timeout=5) as response:
                run_payload = json.loads(response.read().decode("utf-8"))
            with opener.open(f"{base_url}{expected_path}&download=1", timeout=5) as response:
                run_download_payload = json.loads(response.read().decode("utf-8"))
                run_disposition = response.headers.get("Content-Disposition")
            with opener.open(
                f"{base_url}/api/analyze-action?sentence=%20%20&index=0&require_coq=1",
                timeout=5,
            ) as response:
                empty_action_payload = json.loads(response.read().decode("utf-8"))
            with self.assertRaises(HTTPError) as human_review_action:
                opener.open(
                    f"{base_url}/api/analyze-action-run?sentence=%20%20&index=0&require_coq=1",
                    timeout=5,
                )
        self.assertEqual(action_payload["schema_version"], RECOVERY_ACTION_SCHEMA)
        self.assertEqual(action_download_payload, action_payload)
        self.assertEqual(
            action_disposition,
            'attachment; filename="analyze_recovery_action__the-plant-killed__0.json"',
        )
        self.assertEqual(action_payload["source"], "analyze")
        self.assertEqual(action_payload["action"]["kind"], "inspect_ast")
        self.assertEqual(empty_action_payload["action"]["kind"], "edit_input")
        self.assertFalse(empty_action_payload["repair_plan"]["can_auto_run"])
        self.assertEqual(run_payload["schema_version"], RECOVERY_INSPECTION_RUN_SCHEMA)
        self.assertEqual(run_download_payload, run_payload)
        self.assertEqual(
            run_disposition,
            'attachment; filename="analyze_inspection_run__the-plant-killed__0.json"',
        )
        self.assertTrue(run_payload["ok"])
        self.assertEqual(run_payload["inspection_results"]["ast"]["frame"], "inchoative")
        self.assertEqual(human_review_action.exception.code, 400)
        rejection_payload = json.loads(
            human_review_action.exception.read().decode("utf-8")
        )
        self.assertEqual(rejection_payload["schema_version"], RECOVERY_INSPECTION_RUN_SCHEMA)
        self.assertFalse(rejection_payload["ok"])
        self.assertEqual(rejection_payload["source"], "analyze")
        self.assertEqual(rejection_payload["action_kind"], "edit_input")

