    def test_web_page_shows_reading_attachment_type_summaries(self) -> None:
        subject_relative_page = render_page(
            "some boy who quickly saw Mary in the park loved a girl",
            require_coq=True,
        )
        self.assertIn(
            'data-reading-attachment-kind="subject_relative_adv"',
            subject_relative_page,
        )
        self.assertIn("<dt>attachment</dt><dd>subject_relative_adv</dd>", subject_relative_page)
        self.assertIn("<dt>interpretation</dt>", subject_relative_page)
        self.assertIn("Attachment reading subject_relative_adv.", subject_relative_page)
        self.assertIn("subject_relative: quickly : Adv", subject_relative_page)
        self.assertIn("subject_relative: in_park : Adv", subject_relative_page)
        self.assertIn("subject_relative: mary : Entity", subject_relative_page)
        self.assertIn("modify predicates, not Entity constants", subject_relative_page)
        self.assertIn(
            "remain Entity arguments of the relative predicate",
            subject_relative_page,
        )
        self.assertIn("<dt>typed NP restrictors</dt><dd>none</dd>", subject_relative_page)

        object_relative_page = render_page(
            "some boy loved a girl that saw Mary in the park",
            require_coq=True,
        )
        self.assertIn(
            'data-reading-attachment-kind="clause_adv"',
            object_relative_page,
        )
        self.assertIn(
            'data-reading-attachment-kind="object_relative_adv"',
            object_relative_page,
        )
        self.assertIn("clause: in_park : Adv", object_relative_page)
        self.assertIn("object_relative: in_park : Adv", object_relative_page)
        self.assertIn("object_relative: mary : Entity", object_relative_page)
        self.assertIn("Attachment reading object_relative_adv.", object_relative_page)

        object_np_page = render_page(
            "some boy loved some girl in the park with a telescope",
            require_coq=True,
        )
        self.assertIn(
            'data-reading-attachment-kind="object_np_restrictor"',
            object_np_page,
        )
        self.assertIn("object_np: in_park_np : Entity -&gt; Prop", object_np_page)
        self.assertIn("object_np: with_telescope_np : Entity -&gt; Prop", object_np_page)
        self.assertIn("clause: with_telescope : Adv", object_np_page)
        self.assertIn(
            "constrain entity binders, not predicate-level Adv slots",
            object_np_page,
        )

    def test_semantic_readings_check_panel_shows_missing_export_errors(self) -> None:
        panel_html = semantic_readings_check_panel(
            {
                "semantic_readings": [
                    {
                        "name": "missing_reading",
                        "scope": "synthetic_scope",
                        "source": "negative_test",
                        "coq_definition": "missing_reading",
                        "type_check": {"ok": True},
                    }
                ],
                "semantic_readings_check": {
                    "checked": True,
                    "ok": False,
                    "reading_count": 1,
                    "errors": [
                        "semantic_readings[0].coq_definition 'missing_reading' is not exported"
                    ],
                    "repair_details": {
                        "exported_definitions": ["other_reading"],
                        "expected_coq_definitions": ["missing_reading"],
                        "missing_coq_definitions": ["missing_reading"],
                        "duplicate_reading_names": [],
                        "malformed_reading_indices": [],
                        "failed_type_check_indices": [],
                        "expected_export_count": None,
                        "observed_export_count": 1,
                    },
                },
                "coq_code": "Definition other_reading : Prop := True.",
            }
        )
        self.assertIn('data-semantic-readings-status="failed"', panel_html)
        self.assertIn("failed: 1 reading(s)", panel_html)
        self.assertIn(
            "Semantic-reading failure kind(s): missing Coq/Rocq exports.",
            panel_html,
        )
        self.assertIn('data-semantic-reading-kind="missing_coq_export"', panel_html)
        self.assertIn("exported Prop/PropT definitions: other_reading", panel_html)
        self.assertIn("missing Coq/Rocq definitions", panel_html)
