    def test_json_api_route_validation_spec_rejects_invalid_values(self) -> None:
        base = {
            "path": "/api/example",
            "label": "example",
            "expected_statuses": (200,),
            "json_modes": ("example_json",),
        }
        cases = [
            ({**base, "path": "/example"}, "must be an API route"),
            ({**base, "path": "/api/example?download=1"}, "must not include a query"),
            ({**base, "label": " "}, "needs a label"),
            ({**base, "expected_statuses": ()}, "needs statuses"),
            ({**base, "expected_statuses": (99,)}, "invalid HTTP statuses"),
            ({**base, "expected_statuses": (200, 200)}, "duplicate statuses"),
            ({**base, "json_modes": ()}, "needs JSON modes"),
            ({**base, "json_modes": ("example_json", "")}, "empty mode"),
            (
                {**base, "json_modes": ("example_json", "example_json")},
                "duplicate JSON modes",
            ),
            (
                {
                    **base,
                    "text_bypass_modes": ("format=patch", "format=patch"),
                },
                "duplicate text bypass modes",
            ),
            (
                {
                    **base,
                    "json_modes": ("format=patch",),
                    "text_bypass_modes": ("format=patch",),
                },
                "mode overlap",
            ),
        ]
        for kwargs, message in cases:
            with self.subTest(message=message):
                with self.assertRaisesRegex(ValueError, message):
                    JsonApiRouteValidationSpec(**kwargs)

    def test_json_api_route_validation_specs_reject_duplicate_paths(self) -> None:
        spec = JsonApiRouteValidationSpec(
            "/api/example",
            "example",
            (200,),
            ("example_json",),
        )
        with self.assertRaisesRegex(ValueError, "at least one route"):
            validate_json_api_route_validation_specs(())
        with self.assertRaisesRegex(ValueError, "Duplicate JSON route validation paths"):
            validate_json_api_route_validation_specs((spec, spec))
        self.assertEqual(validate_json_api_route_validation_specs((spec,)), (spec,))

    def test_verification_rejects_diagnostic_contract_manifest_drift(self) -> None:
        contract = diagnostic_contract_manifest()
        bad_schema = deepcopy(contract)
        bad_schema["schema_version"] = "diagnostic_contract.v0"
        with self.assertRaisesRegex(SystemExit, "wrong diagnostic contract schema"):
            validate_diagnostic_contract_manifest(bad_schema)

        bad_stages = deepcopy(contract)
        bad_stages["failure_stages"] = ["semantic_readings_check"]
        with self.assertRaisesRegex(SystemExit, "diagnostic failure-stage drift"):
            validate_diagnostic_contract_manifest(bad_stages)

        bad_required = deepcopy(contract)
        bad_required["required_fixture_stages"] = ["semantic_readings_check"]
        with self.assertRaisesRegex(SystemExit, "diagnostic fixture-stage drift"):
            validate_diagnostic_contract_manifest(bad_required)

        bad_actions = deepcopy(contract)
        bad_actions["recovery_action_kinds"] = ["inspect_readings"]
        with self.assertRaisesRegex(SystemExit, "diagnostic recovery-action drift"):
            validate_diagnostic_contract_manifest(bad_actions)

        bad_modes = deepcopy(contract)
        bad_modes["repair_plan_automation_modes"] = ["human_review_required"]
        with self.assertRaisesRegex(
            SystemExit,
            "diagnostic repair-plan automation drift",
        ):
            validate_diagnostic_contract_manifest(bad_modes)

        bad_inspection_kinds = deepcopy(contract)
        bad_inspection_kinds["inspection_only_recovery_action_kinds"] = ["inspect_ast"]
        with self.assertRaisesRegex(
            SystemExit,
            "diagnostic inspection-only action drift",
        ):
            validate_diagnostic_contract_manifest(bad_inspection_kinds)

        bad_semantic_fields = deepcopy(contract)
        bad_semantic_fields["semantic_reading_fields"] = ["name"]
        with self.assertRaisesRegex(
            SystemExit,
            "diagnostic semantic-reading field drift",
        ):
            validate_diagnostic_contract_manifest(bad_semantic_fields)

        bad_route_schema = deepcopy(contract)
        bad_route_schema["json_api_route_validation"]["schema_version"] = (
            "json_api_route_validation.v0"
        )
        with self.assertRaisesRegex(
            SystemExit,
            "wrong JSON route validation schema",
        ):
            validate_diagnostic_contract_manifest(bad_route_schema)

        bad_route_count = deepcopy(contract)
        bad_route_count["json_api_route_validation"]["route_count"] = 0
        with self.assertRaisesRegex(
            SystemExit,
            "JSON route validation route-count drift",
        ):
            validate_diagnostic_contract_manifest(bad_route_count)

        bad_route = deepcopy(contract)
        bad_route["json_api_route_validation"]["routes"] = []
        with self.assertRaisesRegex(
            SystemExit,
            "JSON route validation route drift",
        ):
            validate_diagnostic_contract_manifest(bad_route)

        handler = object.__new__(PipelineHandler)
        route_expectations = json_api_route_expectations_for_handler(handler)
        validate_json_api_route_validation_contract(
            contract["json_api_route_validation"],
            route_expectations,
        )
        stale_route_expectations = dict(route_expectations)
        stale_route_expectations.pop("/api/certified-fragment")
        with self.assertRaisesRegex(
            SystemExit,
            "JSON route expectation coverage drift",
        ):
            validate_json_api_route_validation_contract(
                contract["json_api_route_validation"],
                stale_route_expectations,
            )

