    def test_verification_rejects_analyze_action_export_preview_drift(self) -> None:
        sentence = "the plant killed"
        result = analyze_sentence(sentence, require_coq=True)
        page = render_page(sentence, result=result, require_coq=True)
        action_bundle, status = analyze_action_export_bundle(sentence, True, 0)
        self.assertEqual(status, HTTPStatus.OK)
        validate_analyze_action_export_preview(
            "ordinary type-check failure",
            page,
            0,
            action_bundle,
        )
        expected = html.escape(compact_json(action_bundle))
        stale = expected.replace(
            "diagnostic_recovery_action.v1",
            "diagnostic_recovery_action.v0",
        )
        self.assertNotEqual(expected, stale)
        stale_page = page.replace(expected, stale, 1)
        with self.assertRaisesRegex(
            SystemExit,
            "ordinary action JSON preview",
        ):
            validate_analyze_action_export_preview(
                "ordinary type-check failure",
                stale_page,
                0,
                action_bundle,
            )

    def test_verification_rejects_analyze_action_inspection_rejection_drift(self) -> None:
        sentence = "John"
        result = analyze_sentence(sentence, require_coq=True)
        rejection, status = analyze_action_inspection_run_bundle(sentence, True, 0)
        self.assertEqual(status, HTTPStatus.BAD_REQUEST)
        validate_analyze_action_inspection_run_rejection(
            "ordinary parsing failure",
            sentence,
            0,
            result,
            rejection,
        )
        stale_rejection = deepcopy(rejection)
        stale_rejection["can_auto_run"] = True
        with self.assertRaisesRegex(
            SystemExit,
            "ordinary parsing failure analyze run rejection run drift",
        ):
            validate_analyze_action_inspection_run_rejection(
                "ordinary parsing failure",
                sentence,
                0,
                result,
                stale_rejection,
            )

    def test_verification_rejects_ordinary_failure_scope_drift(self) -> None:
        sentence = "if John left, Mary cried because Sue left"
        result = analyze_sentence(sentence, require_coq=True)
        page = render_page(sentence, result=result, require_coq=True)
        action_bundle, status = analyze_action_export_bundle(sentence, True, 0)
        self.assertEqual(status, HTTPStatus.OK)
        validate_ordinary_analyze_action_export_surface(
            "ordinary unsupported-fragment failure",
            sentence,
            True,
            0,
            result,
            page,
            action_bundle,
            expected_failure_stage="parsing",
            expected_action_kind="revise_sentence",
            expected_can_auto_run=False,
            expected_verification_scope_kind="rejected_unsupported_fragment",
        )
        stale_result = deepcopy(result)
        stale_result["verification_scope"]["kind"] = "unverified_failure"
        with self.assertRaisesRegex(
            SystemExit,
            "ordinary unsupported-fragment failure verification scope kind drift",
        ):
            validate_ordinary_analyze_action_export_surface(
                "ordinary unsupported-fragment failure",
                sentence,
                True,
                0,
                stale_result,
                page,
                action_bundle,
                expected_failure_stage="parsing",
                expected_action_kind="revise_sentence",
                expected_can_auto_run=False,
                expected_verification_scope_kind="rejected_unsupported_fragment",
            )

